SELECT ?point ?type ?label ?series WHERE {
  ?point ref:hasTimeseriesId ?series.
  ?point a ?type.
  ?point rdfs:label ?label.
  FILTER(CONTAINS(STR(?label), "Zone_F2_Z01"))
}

SELECT ?point ?type ?label WHERE {
  ?point a brick:Zone.
  ?point rdfs:label ?label.
  FILTER(CONTAINS(STR(?label), "Core"))
}

