# average by day (occupied hours 8:00-18:00) 
def day_avg(d, hours=(8,18)):
    vals=[v for t,v in d.items() if t[11:13] in [f'{h:02d}' for h in range(*hours) or None]
    # Simpler:
    vals=[v for t,v in d.items() if hours[0] <= int(t[11:13]) < hours[1]]
    return sum(vals)/len(vals) if vals else None

